# --------------------------------------------------------------------------- ASGI


def asgi_app(status: int = 200, fail: bool = False) -> Any:
    async def app(scope: Any, receive: Any, send: Any) -> None:
        if fail:
            raise RuntimeError("handler crashed")
        await send({"type": "http.response.start", "status": status, "headers": []})
        await send({"type": "http.response.body", "body": (current_trace_id() or "").encode()})

    return app


async def call_asgi(app: Any, scope: dict[str, Any]) -> list[dict[str, Any]]:
    sent: list[dict[str, Any]] = []

    async def receive() -> dict[str, Any]:
        return {"type": "http.request", "body": b""}

    async def send(message: dict[str, Any]) -> None:
        sent.append(message)

    await app(scope, receive, send)
    return sent


def http_scope(path: str = "/items", **extra: Any) -> dict[str, Any]:
    return {
        "type": "http",
        "method": "get",
        "path": path,
        "scheme": "https",
        "headers": [(b"traceparent", TRACEPARENT.encode())],
        "server": ("api.local", 443),
        "client": ("10.0.0.1", 5555),
        **extra,
    }


async def test_asgi_server_span(setup: tuple[otel_trace.Tracer, InMemorySpanExporter]) -> None:
    tracer, exporter = setup
    app = TracingASGIMiddleware(asgi_app(), tracer=tracer, propagator=PROPAGATOR)
    sent = await call_asgi(app, http_scope())
    assert sent[1]["body"] == TRACE_ID.encode()  # the app runs inside the span
    (span,) = exporter.spans
    assert span.name == "GET /items"
    assert span.kind == "server"
    assert span.trace_id == TRACE_ID
    assert span.parent_span_id == "00f067aa0ba902b7"
    assert span.attributes["http.response.status_code"] == 200
    assert span.attributes["server.address"] == "api.local"
    assert span.attributes["client.address"] == "10.0.0.1"
    assert span.status.code == "unset"


async def test_asgi_errors_and_passthrough(
    setup: tuple[otel_trace.Tracer, InMemorySpanExporter],
) -> None:
    tracer, exporter = setup
    failing = TracingASGIMiddleware(
        asgi_app(status=503), tracer=tracer, span_namer=lambda scope: "custom"
    )
    await call_asgi(failing, http_scope(headers=[], server=None, client=None))
    assert exporter.spans[0].name == "custom"
    assert exporter.spans[0].status.code == "error"
    assert "server.address" not in exporter.spans[0].attributes
    crashing = TracingASGIMiddleware(asgi_app(fail=True), tracer=tracer)
    with pytest.raises(RuntimeError):
        await call_asgi(crashing, http_scope())
    assert exporter.spans[1].status.code == "error"
    exclusive = TracingASGIMiddleware(asgi_app(), tracer=tracer, excluded_paths=["/health"])
    await call_asgi(exclusive, http_scope("/health"))
    lifespan_calls: list[str] = []

    async def lifespan_app(scope: Any, receive: Any, send: Any) -> None:
        lifespan_calls.append(scope["type"])

    await call_asgi(TracingASGIMiddleware(lifespan_app), {"type": "lifespan"})
    assert lifespan_calls == ["lifespan"]
    assert len(exporter.spans) == 2


async def test_asgi_cancelled_request_is_not_an_error(
    setup: tuple[otel_trace.Tracer, InMemorySpanExporter],
) -> None:
    tracer, exporter = setup

    async def gone(scope: Any, receive: Any, send: Any) -> None:
        raise CancelledError("handler: cancelled")

    with pytest.raises(CancelledError):
        await call_asgi(TracingASGIMiddleware(gone, tracer=tracer), http_scope())
