# --------------------------------------------------------------------------- WSGI


class Body:
    def __init__(self, chunks: Iterable[bytes], fail: bool = False) -> None:
        self.chunks = list(chunks)
        self.fail = fail
        self.closed = False

    def __iter__(self) -> Iterator[bytes]:
        yield from self.chunks
        if self.fail:
            raise OSError("stream broke")

    def close(self) -> None:
        self.closed = True


def environ(path: str = "/w", **extra: Any) -> dict[str, Any]:
    return {
        "REQUEST_METHOD": "POST",
        "PATH_INFO": path,
        "wsgi.url_scheme": "http",
        "SERVER_NAME": "wsgi.local",
        "REMOTE_ADDR": "10.0.0.2",
        "HTTP_TRACEPARENT": TRACEPARENT,
        **extra,
    }


def test_wsgi_server_span(setup: tuple[otel_trace.Tracer, InMemorySpanExporter]) -> None:
    tracer, exporter = setup
    body = Body([b"a", b"b"])
    statuses: list[str] = []

    def app(env: dict[str, Any], start_response: Any) -> Iterable[bytes]:
        assert current_trace_id() == TRACE_ID
        start_response("201 Created", [])
        return body

    middleware = TracingWSGIMiddleware(app, tracer=tracer, propagator=PROPAGATOR)
    result = middleware(environ(), lambda status, headers, exc_info=None: statuses.append(status))
    assert b"".join(result) == b"ab"
    assert exporter.spans == []  # ends on close
    result.close()  # type: ignore[attr-defined]
    assert body.closed
    (span,) = exporter.spans
    assert span.name == "POST /w"
    assert span.parent_span_id == "00f067aa0ba902b7"
    assert span.attributes["http.response.status_code"] == 201
    assert span.attributes["server.address"] == "wsgi.local"
    assert statuses == ["201 Created"]


def test_wsgi_errors_and_exclusions(setup: tuple[otel_trace.Tracer, InMemorySpanExporter]) -> None:
    tracer, exporter = setup

    def broken_stream(env: dict[str, Any], start_response: Any) -> Iterable[bytes]:
        start_response("weird status", [])
        return [b"x"] if env["PATH_INFO"] == "/list" else Body([b"x"], fail=True)

    middleware = TracingWSGIMiddleware(broken_stream, tracer=tracer, span_namer=lambda env: "named")
    result = middleware(environ(SERVER_NAME="", REMOTE_ADDR=""), lambda *a: None)
    with pytest.raises(OSError):
        list(result)
    result.close()  # type: ignore[attr-defined]
    assert exporter.spans[0].status.code == "error"
    assert exporter.spans[0].name == "named"
    plain = middleware(environ("/list"), lambda *a: None)
    list(plain)
    plain.close()  # type: ignore[attr-defined]
    assert "http.response.status_code" not in exporter.spans[1].attributes

    def crash(env: dict[str, Any], start_response: Any) -> Iterable[bytes]:
        raise ValueError("crash")

    with pytest.raises(ValueError):
        TracingWSGIMiddleware(crash, tracer=tracer)(environ(PATH_INFO=""), lambda *a: None)
    assert exporter.spans[2].status.code == "error"
    assert exporter.spans[2].attributes["url.path"] == "/"
    excluded = TracingWSGIMiddleware(broken_stream, tracer=tracer, excluded_paths=["/list"])
    assert excluded(environ("/list"), lambda *a: None) == [b"x"]
    assert len(exporter.spans) == 3


