def handler(request: httpx.Request) -> httpx.Response:
    status = 404 if request.url.path == "/missing" else 200
    return httpx.Response(status, json={"traceparent": request.headers.get("traceparent")})


def test_httpx_hooks(setup: tuple[otel_trace.Tracer, InMemorySpanExporter]) -> None:
    tracer, exporter = setup
    with httpx.Client(
        transport=httpx.MockTransport(handler),
        event_hooks=httpx_event_hooks(tracer=tracer, propagator=PROPAGATOR),
    ) as client:
        ok = client.get("http://svc.local:8080/items?token=abc")
        missing = client.get("https://svc.local/missing")
    first, second = exporter.spans
    assert ok.json()["traceparent"].split("-")[2] == first.span_id
    assert first.name == "GET"
    assert first.kind == "client"
    assert first.attributes["server.port"] == 8080
    assert "abc" not in str(first.attributes["url.full"])
    assert first.status.code == "unset"
    assert second.status.code == "error"
    assert missing.status_code == 404


