def test_requests_session(setup: tuple[otel_trace.Tracer, InMemorySpanExporter]) -> None:
    requests = pytest.importorskip("requests")
    tracer, exporter = setup
    seen_headers: list[str | None] = []

    class Adapter(requests.adapters.BaseAdapter):  # type: ignore[misc]
        def send(self, request: Any, **kwargs: Any) -> Any:
            if "fail" in request.url:
                raise requests.ConnectionError("refused")
            seen_headers.append(request.headers.get("traceparent"))
            assert current_trace_id() is not None
            response = requests.Response()
            response.status_code = 500 if "boom" in request.url else 200
            response.request = request
            return response

        def close(self) -> None:
            pass

    session = requests.Session()
    session.mount("http://", Adapter())
    assert instrument_requests_session(session, tracer=tracer, propagator=PROPAGATOR) is session
    assert instrument_requests_session(session) is session  # idempotent
    assert session.get("http://svc.local/ok").status_code == 200
    assert session.get("http://svc.local/boom").status_code == 500
    with pytest.raises(requests.ConnectionError):
        session.get("http://svc.local/fail")
    ok, boom, fail = exporter.spans
    assert seen_headers[0] is not None
    assert seen_headers[0].split("-")[2] == ok.span_id
    assert ok.status.code == "unset"
    assert boom.status.code == "error"
    assert fail.status.code == "error"
    assert fail.events[0].name == "exception"
    session.close()
